begin;select plan(37);
select has_table('public','creator_trust_evaluations','trust evaluations exist');select has_table('public','creator_trust_signals','trust signals exist');select has_table('public','creator_trust_recommendations','trust recommendations exist');select has_table('public','creator_trust_events','trust events exist');
select ok((select relforcerowsecurity from pg_class where oid='public.creator_trust_evaluations'::regclass),'evaluation RLS forced');select ok((select relforcerowsecurity from pg_class where oid='public.creator_trust_signals'::regclass),'signal RLS forced');select ok((select relforcerowsecurity from pg_class where oid='public.creator_trust_recommendations'::regclass),'recommendation RLS forced');select ok((select relforcerowsecurity from pg_class where oid='public.creator_trust_events'::regclass),'event RLS forced');
select table_privs_are('public','creator_trust_evaluations','anon',array[]::text[],'anon has no evaluation privileges');select table_privs_are('public','creator_trust_signals','anon',array[]::text[],'anon has no signal privileges');select function_privs_are('public','evaluate_creator_trust',array['uuid','text','integer','integer','integer','integer'],'authenticated',array[]::text[],'browser cannot evaluate');select function_privs_are('public','claim_trust_evaluations',array['integer','uuid'],'service_role',array['EXECUTE'],'service worker can claim');
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,recovery_token,email_change_token_new,email_change)values('00000000-0000-0000-0000-000000000000','b6000000-0000-4000-8000-000000000001','authenticated','authenticated','trust-owner@example.com',crypt('pw',gen_salt('bf')),now(),'{}','{}',now(),now(),'','','',''),('00000000-0000-0000-0000-000000000000','b6000000-0000-4000-8000-000000000002','authenticated','authenticated','trust-other@example.com',crypt('pw',gen_salt('bf')),now(),'{}','{}',now(),now(),'','','','');
update public.creators set display_name='Trust Creator',public_slug='trust-creator',public_profile_enabled=true where owner_user_id='b6000000-0000-4000-8000-000000000001';select set_config('tests.trust_creator',(select id::text from public.creators where public_slug='trust-creator'),true);
set local role authenticated;select set_config('request.jwt.claim.sub','b6000000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"b6000000-0000-4000-8000-000000000001","role":"authenticated"}',true);select lives_ok($$select public.ensure_creator_identity_profile()$$,'owner creates profile');select throws_ok($$insert into public.creator_trust_evaluations(creator_id,identity_profile_id,trust_state,policy_version,internal_score,strong_signal_count,valid_signal_count,stale_signal_count,warning_count,blocker_count,evaluated_at,source_revision)select creator_id,id,'verified','forged',100,1,0,0,0,0,now(),identity_revision from public.creator_identity_profiles$$,'42501',null,'creator cannot forge evaluation');
reset role;set local role service_role;select set_config('request.jwt.claim.role','service_role',true);insert into public.creator_identity_accounts(identity_profile_id,creator_id,provider,stable_provider_account_id,canonical_profile_url,account_kind,verification_status,verification_method,verification_confidence,official,primary_for_provider,first_verified_at,last_verified_at,last_revalidated_at,last_synced_at,sync_status)select id,creator_id,'youtube','trust-channel','https://youtube.com/channel/trust','channel','verified','oauth','high',true,true,now(),now(),now(),now(),'healthy'from public.creator_identity_profiles;
select lives_ok($$select public.evaluate_creator_trust((select id from public.creator_identity_profiles))$$,'evaluation succeeds');select is((select trust_state from public.creator_trust_evaluations order by evaluated_at desc limit 1),'verified','one family is verified');select is((select count(*)::integer from public.creator_trust_signals),1,'one authoritative signal');select lives_ok($$select public.evaluate_creator_trust((select id from public.creator_identity_profiles))$$,'same revision evaluation is idempotent');select is((select count(*)::integer from public.creator_trust_evaluations),1,'idempotency prevents duplicate evaluation');select ok(public.get_public_creator_trust('trust-creator')::text!~'internal_score|weight|reason_code|metadata|source_revision','public trust hides internals');
insert into public.creator_identity_domains(identity_profile_id,creator_id,hostname,canonical_url,verification_status,verification_method,verification_confidence,first_verified_at,last_verified_at,last_checked_at,official,primary_domain)select id,creator_id,'trust.example','https://trust.example','verified','dns','high',now(),now(),now(),true,true from public.creator_identity_profiles;select ok((select identity_revision>2 from public.creator_identity_profiles),'domain mutation increments source revision');select lives_ok($$select public.evaluate_creator_trust((select id from public.creator_identity_profiles))$$,'changed revision reevaluates');select is((select trust_state from public.creator_trust_evaluations order by evaluated_at desc limit 1),'strongly_verified','independent domain produces strong trust');
update public.creator_identity_accounts set provider='instagram',stable_provider_account_id='meta-one'where provider='youtube';insert into public.creator_identity_accounts(identity_profile_id,creator_id,provider,stable_provider_account_id,canonical_profile_url,account_kind,verification_status,verification_method,verification_confidence,official,first_verified_at,last_verified_at,last_revalidated_at,last_synced_at,sync_status)select id,creator_id,'facebook','meta-two','https://facebook.com/trust','page','verified','oauth','high',true,now(),now(),now(),now(),'healthy'from public.creator_identity_profiles;update public.creator_identity_domains set verification_status='archived',official=false,primary_domain=false,public_visible=false;select lives_ok($$select public.evaluate_creator_trust((select id from public.creator_identity_profiles))$$,'same-family accounts evaluate');select is((select trust_state from public.creator_trust_evaluations order by evaluated_at desc limit 1),'verified','same Meta family is not independent');
update public.creator_identity_accounts set last_revalidated_at=now()-interval'30 days';select lives_ok($$select public.evaluate_creator_trust((select id from public.creator_identity_profiles),p_provider_freshness_hours=>24)$$,'stale evidence evaluates');select is((select trust_state from public.creator_trust_evaluations order by evaluated_at desc limit 1),'unverified','only stale evidence does not verify');select ok(exists(select 1 from public.creator_trust_recommendations where recommendation_code='refresh_stale_identity'),'stale recommendation generated');
update public.creator_identity_accounts set verification_status='revoked',official=false,primary_for_provider=false,public_visible=false,revoked_at=now();select lives_ok($$select public.evaluate_creator_trust((select id from public.creator_identity_profiles))$$,'revoked evidence evaluates');select is((select trust_state from public.creator_trust_evaluations order by evaluated_at desc limit 1),'restricted','revocation restricts trust');select is(jsonb_array_length(public.get_public_creator_trust('trust-creator')->'signals'),0,'restricted public signals suppressed');select throws_ok($$update public.creator_trust_events set event_type='forged'$$,'55000','emergency history is immutable','trust events append only');
select is((select count(*)::integer from public.claim_trust_evaluations(10,'b6000000-0000-4000-8000-000000000009')),0,'current evaluation is not leased');select throws_ok($$select public.evaluate_creator_trust((select id from public.creator_identity_profiles),'future-policy')$$,'22023','unsupported trust policy','unknown policy rejected');
reset role;set local role authenticated;select set_config('request.jwt.claim.sub','b6000000-0000-4000-8000-000000000002',true);select set_config('request.jwt.claims','{"sub":"b6000000-0000-4000-8000-000000000002","role":"authenticated"}',true);select is((select count(*)::integer from public.creator_trust_evaluations),0,'other creator cannot read evaluations');select is((select count(*)::integer from public.creator_trust_signals),0,'other creator cannot read signals');select throws_ok($$select public.get_creator_trust()$$,'42501','access denied','cross-creator trust read denied');
select * from finish();rollback;
